def solve(inputs: dict) -> float:
    """
    Compute the final numerator of a continued fraction.
    inputs contains 'terms' list of continued fraction coefficients.
    Uses recurrence: p_i = a_i * p_(i-1) + p_(i-2)
    with p_(-1) = 1, p_0 = a_0
    """
    terms = inputs['terms']

    if len(terms) == 0:
        return 1.0

    p_prev2 = 1  # p_(-1)
    p_prev1 = terms[0]  # p_0

    if len(terms) == 1:
        return float(p_prev1)

    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    return float(p_prev1)

